def clean(df):
    df = df.copy()
    df['Region'] = df['Region'].str.strip().str.title()
    df['Quantity'] = df['Quantity'].abs()
    df['Revenue'] = df['Revenue'].abs()
    return df

def answer(df):
    electronics = df[df['Category'] == 'Electronics'].dropna(subset=['Region'])
    result = electronics.groupby('Region')['Revenue'].sum()
    return result.to_dict()
